// Video — Gtk.Video
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles video with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { GraphicsOffloadEnabled } from "@/lib/enums"

export interface VideoProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Gtk.Video */
  autoplay?: boolean

  /** Gio.File, from Gtk.Video */
  file?: ReactNode

  /** GraphicsOffloadEnabled, from Gtk.Video */
  graphicsOffload?: GraphicsOffloadEnabled

  /** gboolean, from Gtk.Video */
  loop?: boolean

  /** MediaStream, from Gtk.Video */
  mediaStream?: ReactNode
}

export function Video({ className, children }: VideoProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
